          ..write('completedAtUtc: $completedAtUtc, ')
          ..write('lastFailureCategory: $lastFailureCategory, ')
          ..write('createdAtUtc: $createdAtUtc, ')
          ..write('updatedAtUtc: $updatedAtUtc, ')
          ..write('rowid: $rowid')
          ..write(')'))
